import pixeltable as pxl

@pxl.udf
def word_count(text: str) -> int:
    """Count the number of words in a text string."""
    if not text:
        return 0
    return len(text.split())

# Get the existing docs table and add the computed column
table = pxl.get_table('docs')
table.add_column('n_words', word_count(table.content))
